class Connection:
    def __init__(self, name):
        self.name = name

first = Connection('first')
second = Connection('second')
pool = ConnectionPool([first, second])
held = {pool.acquire(), pool.acquire()}
assert held == {first, second}
pool.release(first)
assert pool.acquire() is first
pool.release(first)
pool.release(second)

class EqualConnection:
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        return isinstance(other, EqualConnection)

    __hash__ = object.__hash__

owned = EqualConnection('owned')
foreign = EqualConnection('foreign')
pool = ConnectionPool([owned])
checked_out = pool.acquire()
assert checked_out is owned
for invalid in (foreign,):
    try:
        pool.release(invalid)
        raise AssertionError('expected ValueError for a foreign connection')
    except ValueError:
        pass
pool.release(owned)
try:
    pool.release(owned)
    raise AssertionError('expected ValueError for a repeated release')
except ValueError:
    pass
assert pool.acquire() is owned
